/** Read-only, snapshot-scoped analysis. An exact cover is NOT approval to remove a grant. */
class PermissionCover {
    static final Set BUILT_INS = ['ADMINISTER', 'SYSTEM_ADMIN', 'USE', 'USER_PICKER',
        'CREATE_SHARED_OBJECTS', 'MANAGE_GROUP_FILTER_SUBSCRIPTIONS', 'BULK_CHANGE'] as Set

    static Map analyse(Set holders, Map groupMembers, long maxMembershipChecks = 2000000L) {
        if (holders == null || groupMembers == null || groupMembers.any { k, v ->
            !(k instanceof String) || !k.trim() || !(v instanceof Set) || v.contains(null)
        } || holders.contains(null) || maxMembershipChecks <= 0) {
            throw new IllegalArgumentException('Invalid coverage inputs')
        }
        def target = new HashSet(holders)
        def base = [holderCount:target.size(), candidateGroupCount:groupMembers.size(),
                    selectedGroups:[], unselectedGroups:[], lostCount:0, gainedCount:0]
        long work = 0L
        for (def users : groupMembers.values()) {
            work += users.size()
            if (work > maxMembershipChecks) return base + [status:'BLOCKED', reason:'WORK_BUDGET']
        }
        def candidates = new TreeMap()
        groupMembers.each { name, users -> candidates[name] = new HashSet(users) }

        def allMembers = new HashSet()
        candidates.values().each { allMembers.addAll(it) }
        def lost = target - allMembers
        def gained = allMembers - target
        if (lost || gained) return base + [status:'UNSUPPORTED_COVERAGE',
                                          lostCount:lost.size(), gainedCount:gained.size()]
        if (!target) return base + [status:'EMPTY_SCOPE']
        def remaining = new HashSet(target)
        def chosen = []
        while (remaining) {
            String best = null
            int bestGain = 0
            // Sorted iteration and strict > make equal-gain ties deterministic.
            for (def entry : candidates.entrySet()) {
                String name = entry.key
                Set users = entry.value
                if (!chosen.contains(name)) {
                    int gain = 0
                    for (def id : users) {
                        if (++work > maxMembershipChecks) return base + [status:'BLOCKED', reason:'WORK_BUDGET']
                        if (remaining.contains(id)) gain++
                    }
                    if (gain > bestGain) { best = name; bestGain = gain }
                }
            }
            if (best == null) return base + [status:'UNSUPPORTED_COVERAGE', lostCount:remaining.size()]
            chosen.add(best)
            remaining.removeAll(candidates[best])
        }
        def covered = new HashSet()
        chosen.each { covered.addAll(candidates[it]) }
        lost = target - covered
        gained = covered - target
        if (lost || gained) return base + [status:'UNSUPPORTED_COVERAGE',
                                          lostCount:lost.size(), gainedCount:gained.size()]
        base + [status:'EXACT_SNAPSHOT', selectedGroups:chosen,
                unselectedGroups:candidates.keySet().findAll { !chosen.contains(it) }.toList()]
    }

    static Map run(Map services, Object key, Map config) {
        try {
            guard(config?.permissionKey instanceof String && config.permissionKey.trim() &&
                  !config.permissionKey.startsWith('REPLACE_'), 'CONFIGURE_PERMISSION_KEY')
            guard(!BUILT_INS.contains(config.permissionKey), 'BUILT_IN_PERMISSION')
            guard(config.appPermissionConfirmed == true, 'APP_SCOPE_NOT_CONFIRMED')
            ['maxUsers', 'maxGroups', 'maxMembersPerGroup'].each {
                guard(config[it] instanceof Integer && config[it] > 0, 'INVALID_LIMIT')
            }
            def budget = config.containsKey('maxMembershipChecks') ? config.maxMembershipChecks : 2000000L
            guard((budget instanceof Integer || budget instanceof Long) && budget > 0, 'INVALID_LIMIT')
            def limits = config + [maxMembershipChecks:budget]
            def first = snapshot(services, key, limits)
            def second = snapshot(services, key, limits)
            guard(first == second, 'OBSERVATIONS_CHANGED')
            def result = analyse(second.holders, second.members, budget as long)
            if (config.showGroupNames != true) {
                def aliases = [:]
                second.members.keySet().sort().eachWithIndex { name, i -> aliases[name] = "Group ${i + 1}".toString() }
                result.selectedGroups = result.selectedGroups.collect { aliases[it] }
                result.unselectedGroups = result.unselectedGroups.collect { aliases[it] }
            }
            return result + [readOnly:true, atomicSnapshot:false,
                scope:'Active users with any licensed application role',
                warning:'Review only. Not a deletion plan. No guarantee for future membership or out-of-scope accounts.']
        } catch (CoverReadBlocked blocked) {
            return [status:'BLOCKED', reason:blocked.code, readOnly:true]
        } catch (Exception ignored) {
            // A directory/API error can contain real names or configuration. Do not return its text.
            return [status:'BLOCKED', reason:'READ_OR_API_ERROR', readOnly:true]
        }
    }

    private static Map snapshot(Map services, Object key, Map config) {
        def descriptor = services.permissions.getGlobalPermission(key)
        guard(descriptor != null && readBoolean(descriptor.isDefined()), 'UNKNOWN_PERMISSION')
        def rows = collection(services.permissions.getPermissions(key))
        def rowNames = rows.collect { it.group }
        def names = collection(services.permissions.getGroupNamesWithPermission(key))
        guard((rowNames + names).every { it instanceof String && it.trim() }, 'ANONYMOUS_OR_EMPTY_GRANT')
        guard(!readBoolean(services.anonymousAllowed.call()), 'ANONYMOUS_ACCESS')
        def grantNames = new TreeSet(names)
        guard((rowNames as Set) == grantNames, 'GRANT_READS_DISAGREE')
        guard(grantNames.size() <= config.maxGroups, 'GROUP_LIMIT')
        grantNames.each { guard(readBoolean(services.groups.groupExists(it)), 'UNRESOLVED_GROUP') }

        def allUsers = collection(services.users.getAllApplicationUsers())
        guard(allUsers.size() <= config.maxUsers, 'USER_LIMIT')
        def allKeys = new HashSet()
        def scope = new HashSet()
        def holders = new HashSet()
        allUsers.each { u ->
            def id = identity(u)
            guard(allKeys.add(id), 'DUPLICATE_USER_IDENTITY')
            guard(u.active instanceof Boolean, 'UNRESOLVED_USER')
            if (u.active && readBoolean(services.roles.hasAnyRole(u))) {
                scope.add(id)
                if (readBoolean(services.permissions.hasPermission(key, u))) holders.add(id)
            }
        }
        def members = new TreeMap()
        long totalMemberships = 0L
        grantNames.each { name ->
            def users = collection(services.groups.getUsersInGroup(name))
            guard(users.size() <= config.maxMembersPerGroup, 'MEMBERSHIP_LIMIT')
            totalMemberships += users.size()
            guard(totalMemberships <= config.maxMembershipChecks, 'TOTAL_MEMBERSHIP_LIMIT')
            def scopedMembers = new HashSet()
            users.each { u ->
                def id = identity(u)
                guard(allKeys.contains(id), 'UNRESOLVED_USER')
                if (scope.contains(id)) scopedMembers.add(id)
            }
            members[name] = scopedMembers
        }
        [allKeys:allKeys, scope:scope, holders:holders, members:members]
    }

    private static Collection collection(Object value) {
        guard(value instanceof Collection, 'INCOMPLETE_API_RESULT')
        (Collection) value
    }

    private static boolean readBoolean(Object value) {
        guard(value instanceof Boolean, 'INVALID_BOOLEAN_RESULT')
        (boolean) value
    }

    private static String identity(Object user) {
        guard(user != null && user.key instanceof String && user.key.trim(), 'UNRESOLVED_USER')
        user.key
    }

    private static void guard(boolean condition, String code) {
        if (!condition) throw new CoverReadBlocked(code)
    }
}

class CoverReadBlocked extends RuntimeException {
    final String code
    CoverReadBlocked(String code) { super(code); this.code = code }
}
